// Función para obtener el código del modelo
function getModeloCode(modelo) {
  if (!modelo) return '';

  const modeloLower = modelo.toLowerCase();

  // Mapeo de modelos a códigos según la tabla
  if (modeloLower.includes('hilux')) {
    return '1';
  } else if (modeloLower.includes('corolla cross')) {
    return '245';
  } else if (modeloLower.includes('corolla') && !modeloLower.includes('cross')) {
    return '2';
  } else if (modeloLower.includes('yaris')) {
    return '227';
  } else if (modeloLower.includes('etios')) {
    return '225';
  } else if (modeloLower.includes('sw4')) {
    return '226';
  } else if (modeloLower.includes('hiace')) {
    return '224';
  } else if (modeloLower.includes('rav4') || modeloLower.includes('rav 4')) {
    return '3';
  }

  return ''; // Si no encuentra coincidencia
}

// Función para parsear el modelo del vehículo
function parseModelo(modeloCompleto) {
  if (!modeloCompleto || modeloCompleto === 'no_definido') {
    return { modelo: '', version: '', modelo_code: '' };
  }

  const palabras = modeloCompleto.trim().split(' ');
  const modelo = palabras[0] || '';
  const version = palabras.slice(1).join(' ') || '';
  const modelo_code = getModeloCode(modeloCompleto);

  return {
    modelo: modelo,
    version: version,
    modelo_code: modelo_code
  };
}

// Función para procesar información de financiación
function parseFinanciacion(financiacion) {
  if (!financiacion) return { monto: '', diferencia: '' };

  const result = { monto: '', diferencia: '' };

  // Buscar monto
  const montoMatch = financiacion.match(/monto:\s*(\d+)/i);
  if (montoMatch) {
    result.monto = montoMatch[1];
  }

  // Buscar diferencia
  const diferenciaMatch = financiacion.match(/diferencia:\s*(\d+)/i);
  if (diferenciaMatch) {
    result.diferencia = diferenciaMatch[1];
  }

  return result;
}

// Función para procesar información de usado
function parseUsado(usado) {
  if (!usado) return '';

  // Si es un string con información del usado, lo retornamos tal cual
  return usado;
}

// Función para mapear sucursal a código de boca de venta
function getBocaVenta(sucursal) {
  if (!sucursal || sucursal === 'no_definida') return '';

  const sucursalUpper = sucursal.toUpperCase();

  // Mapeo de sucursales según códigos especificados
  if (sucursalUpper.includes('TANDIL')) {
    return 'TAND';
  } else if (sucursalUpper.includes('TRES ARROYOS') || sucursalUpper.includes('3 ARROYOS')) {
    return '3ARR';
  } else if (sucursalUpper.includes('NECOCHEA')) {
    return 'NECO';
  }

  return '';
}

// Procesar los datos de entrada de n8n
const data = $("When Executed by Another Workflow").first().json;

// Extraer datos de close_conversation
// El input puede venir como array o como objeto directo
let closeData = {};

if (Array.isArray(data)) {
  closeData = data[0] || {};
} else if (data.modelo) {
  // Si ya viene como objeto directo
  closeData = data;
} else if (data.close_conversation) {
  // Si viene dentro de una propiedad
  closeData = data.close_conversation;
}

// Parsear información
const modeloInfo = parseModelo(data.modelo);
const financiacionInfo = parseFinanciacion(data.financiacion);
const usadoInfo = parseUsado(data.usado);
const bocaVenta = getBocaVenta(data.sucursal);

// Obtener fecha actual en formato yyyy-MM-dd
const fechaActual = new Date().toISOString().split('T')[0];

// Determinar forma de pago
let formaPago = '';
if (data.forma_pago && data.forma_pago !== 'no_definido') {
  formaPago = data.forma_pago;
}

// Determinar si tiene auto entregado
let autoEntregado = 'No';
if (usadoInfo && usadoInfo !== '') {
  autoEntregado = 'Sí';
}

// Construir comentarios
let comentarios = '';
if (data.origen === 'plan') {
  comentarios = 'Interesado en Plan Toyota. ';
}
if (financiacionInfo.monto) {
  comentarios += `Financiación - Monto inicial: ${financiacionInfo.monto}. `;
}
if (financiacionInfo.diferencia) {
  comentarios += `Diferencia: ${financiacionInfo.diferencia}. `;
}
if (usadoInfo) {
  comentarios += `Usado a entregar: ${usadoInfo}. `;
}
if (data.sucursal && data.sucursal !== 'no_definida') {
  comentarios += `Sucursal solicitada: ${data.sucursal}.`;
}

comentarios = comentarios.trim();

// Crear resultado con campos desmantelados
const resultado = {
  // Campos básicos
  requestdate: fechaActual,
  nombre: data.name || '',
  telefono: data.tel || '',

  // Información del vehículo
  modelo: modeloInfo.modelo,
  version: modeloInfo.version,
  modelo_code: modeloInfo.modelo_code,
  marca: 'Toyota',
  origen: data.origen || '',

  // Información de la operación
  formaPago: formaPago,
  autoEntregado: autoEntregado,
  comentarios: comentarios,

  // Información de financiación
  monto_inicial: financiacionInfo.monto,
  diferencia: financiacionInfo.diferencia,
  usado_entrega: usadoInfo,
  sucursal: data.sucursal || '',
  boca_de_venta: bocaVenta,
};

// Retornar para n8n
return [{ json: resultado }];

